CREATE DATABASE lab13;
\c lab13

CREATE TABLE orders (
    order_id    bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    customer_id integer       NOT NULL,
    status      text          NOT NULL,
    amount      numeric(10,2) NOT NULL,
    updated_at  timestamptz   NOT NULL DEFAULT now()
) WITH (autovacuum_enabled = false);

INSERT INTO orders (customer_id, status, amount, updated_at)
SELECT (random() * 5000)::int + 1,
       'new',
       round((random() * 9000 + 100)::numeric, 2),
       now() - (g || ' minutes')::interval
  FROM generate_series(1, 200000) AS g;

CREATE INDEX idx_orders_customer ON orders (customer_id);
CREATE INDEX idx_orders_updated  ON orders (updated_at);

ANALYZE orders;

SELECT relname, n_live_tup, n_dead_tup, n_tup_upd, n_tup_hot_upd
  FROM pg_stat_user_tables
 WHERE relname = 'orders';

CREATE EXTENSION pgstattuple;
\x on
SELECT * FROM pgstattuple('orders');
\x off

SELECT relname, n_live_tup, n_dead_tup
  FROM pg_stat_user_tables
 WHERE relname = 'orders';

SELECT table_len, tuple_percent, dead_tuple_count, free_percent
  FROM pgstattuple('orders');

