(2 rows)

SELECT pg_size_pretty(pg_relation_size('orders')) AS table_size,
       pg_size_pretty(pg_indexes_size('orders'))  AS index_size;
SELECT tuple_count, dead_tuple_count, free_percent FROM pgstattuple('orders');

UPDATE orders SET status = 'shipped', updated_at = now();
UPDATE orders SET status = 'delivered', updated_at = now();
VACUUM orders;

CLUSTER orders USING orders_pkey;
SELECT pg_stat_reset_single_table_counters('orders'::regclass);

UPDATE orders SET status = 'returned' WHERE order_id % 50 = 7;

SELECT n_tup_upd, n_tup_hot_upd,
       round(100.0 * n_tup_hot_upd / nullif(n_tup_upd, 0), 1) AS hot_pct
  FROM pg_stat_user_tables
 WHERE relname = 'orders';

ALTER TABLE orders SET (fillfactor = 80);
CLUSTER orders;
SELECT reloptions FROM pg_class WHERE relname = 'orders';
SELECT pg_size_pretty(pg_relation_size('orders')) AS table_size;

SELECT pg_stat_reset_single_table_counters('orders'::regclass);
UPDATE orders SET status = 'refunded' WHERE order_id % 50 = 7;

SELECT indexrelid::regclass AS index_name, indrelid::regclass AS table_name
  FROM pg_index
 WHERE NOT indisvalid;

